// app/api/cms-webhook/route.ts: a webhook cannot use updateTag
import { revalidateTag } from 'next/cache'
export async function POST(req: Request) {
if (req.headers.get('x-cms-secret') !== process.env.CMS_WEBHOOK_SECRET) {
return new Response('forbidden', { status: 403 })
}
const { tag } = await req.json()
revalidateTag(String(tag), 'max')
return Response.json({ ok: true })
}
When any of these runs inside a Server Action, the whole client router cache is cleared, bypassing stale times. revalidatePath is implemented on top of tags: it calls revalidateTag with a special default tag for that page.
Common pitfall: on a multi-instance self-hosted deployment, revalidateTag on one instance invalidates only that instance's cache by default. Coordinating tags needs a shared cache handler that implements refreshTags() (Post 03).

// app/projects/actions.ts
'use server'
import { z } from 'zod'
import { createProject } from '@/data/projects'
import { redirect } from 'next/navigation'
const Schema = z.object({ name: z.string().min(1).max(80) })
export type State = { error?: string }
export async function create(prev: State, formData: FormData): Promise<State> {
const parsed = Schema.safeParse({ name: formData.get('name') })
if (!parsed.success) return { error: 'Name is required (max 80 characters).' }
const project = await createProject(parsed.data.name) // authenticates inside
redirect(`/projects/${project.id}`) // throws: code after it does not run
}
// app/projects/new/form.tsx
'use client'
import { useActionState } from 'react'
import { useFormStatus } from 'react-dom'
import { create, type State } from '../actions'
function Submit() {
const { pending } = useFormStatus()
return <button disabled={pending}>{pending ? 'Creating…' : 'Create'}</button>
}
export function NewProjectForm() {
const [state, action] = useActionState<State, FormData>(create, {})
return (
<form action={action}>
<input name="name" required maxLength={80} />
{state.error && <p role="alert">{state.error}</p>}
<Submit />
</form>
)
}
The form is a real HTML <form> posting to the page URL, so it can submit before JavaScript has loaded (progressive enhancement). useActionState replaced the earlier useFormState from React canaries (the name in Next.js 14 era code).
For instant feedback, useOptimistic shows the expected result while the action runs and rolls back automatically if it fails.

The single most important fact: an exported Server Action is reachable by anyone who can send the same POST, whether or not your UI renders the form. A page-level auth check protects the page's HTML, not the action.
'use server'
import { auth } from '@/lib/auth'
import { db } from '@/lib/db'
// UNSAFE: no authentication, no ownership check, trusts the whole object
export async function completeItemUnsafe(item: { id: string }) {
await db.item.update({ where: { id: item.id }, data: { completed: true } })
}
// SAFE: identity from the session, ownership in the query, minimal return
export async function completeItem(itemId: string) {
const session = await auth()
if (!session?.user) throw new Error('Unauthorized')
const item = await db.item.findFirst({ where: { id: itemId, ownerId: session.user.id } })
if (!item) throw new Error('Forbidden')
await db.item.update({ where: { id: item.id }, data: { completed: true } })
return { ok: true }
}
Checklist for every action:
Authenticate (is there a user?) and authorise (may this user touch this resource?). Missing authorisation is an IDOR bug.
Validate input with a schema. Schema validation checks shape, not ownership.
Return the minimum. Return values are serialised to the client; never return a raw database row.
Keep it thin. Delegate to the server-only DAL so the checks live in one place.
